// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, description, pixelWidth, pixelHeight}, i) => ({
      image: src, description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (material.answersFile ?? (reviewedKey ? 'reviewed-' + grade : grade + '-answers') + '.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2011, "4-5", [{"author":"Н. Добрушина","question":"Герой детской повести Анатолия Алексина «Очень страшная история» писал любовные стихи и посвящал их прекрасным дамам. Первое его стихотворение было посвящено А. Я., второе — Б. Ю. Кому было посвящено третье?","choices":["Г. Д.","У. Ю.","Е. Э.","Г. О.","В. Э."],"key":"Д","review":["Кому посвящены стихи?","Сравни первые буквы пар: А, Б, дальше В. Это начало русского алфавита.","Вторые буквы идут от конца алфавита: Я, Ю, дальше Э. Поэтому третье посвящение — В. Э."]},{"author":"Б. Иомдин","question":"Объясняя значение этого слова, разные словари упоминают полынь, перец, горчицу, кофе… Что это за слово?","choices":["<em>горький</em>","<em>кислый</em>","<em>острый</em>","<em>сладкий</em>","<em>солёный</em>."],"key":"А","review":["Вкус в словаре","Вспомни вкус полыни и чёрного кофе. Так же описывают горчицу и некоторые сорта перца.","Общее слово — «горький». «Острый» подходит для перца или горчицы, но не передаёт обычный вкус полыни и кофе."]},{"author":"Е. Муравенко и А. Пиперски","question":"Если взять слово <em>Румыния</em> и отбросить две последние буквы, получится название жителя этой страны: <em>румын</em>. Из названия какой страны можно тем же способом получить название её жителя?","choices":["<em>Швеция</em>","<em>Швейцария</em>","<em>Грузия</em>","<em>Киргизия</em>","<em>Эстония</em>."],"key":"Г","review":["Из страны в её жителя","Убери «ия» в конце названий. Получатся «швец», «швейцар», «груз», «киргиз», «эстон».","«Киргиз» уже называет жителя Киргизии. «Швейцар» — работник у входа, а для остальных нужны формы «швед», «грузин», «эстонец»."]},{"author":"Л. Фёдорова","question":"Чтобы люди улыбнулись, в Англии фотографы просят их произнести слово <em>чииз</em> (‘сыр’), в Корее — <em>кимчи</em> (‘блюдо из капусты’). Какое слово больше остальных подходит для русского фотографа?","choices":["<em>ананас</em>","<em>урюк</em>","<em>окорок</em>","<em>ириски</em>","<em>эскимо</em>."],"key":"Г","review":["Слово для фотографии","Произнеси «чииз» и «кимчи». Звук [и] тянет уголки губ в стороны и помогает изобразить улыбку.","В слове «ириски» три [и], и на последнем губы всё ещё растянуты. Поэтому оно из списка подходит лучше всего."]},{"author":"И. Рубанов","question":"Какое из этих слов по смыслу отличается от остальных сильнее, чем они\n— друг от друга?","choices":["<em>балабол</em>","<em>баскетбол</em>","<em>бейсбол</em>","<em>волейбол</em>","<em>футбол</em>."],"key":"А","review":["Слова на «-бол»","В баскетболе, бейсболе, волейболе и футболе играют с мячом. Их общая часть «бол» пришла из английского ball — «мяч».","Балаболом называют болтуна. Конец слова звучит похоже на спортивные названия, хотя значение совсем другое."]},{"author":"Б. Иомдин","question":"Кто из этих персонажей наверняка назван по имени-отчеству?","choices":["<em>Добрыня Никитич</em>","<em>Алёша Попович</em>","<em>Илья Муромец</em>","<em>Иван-Царевич</em>","<em>старик Хоттабыч</em>."],"key":"А","review":["Имя и отчество героя","Отчество образуется от имени отца: «Никита» даёт «Никитич». «Добрыня» — имя героя.","«Муромец» указывает на Муром, «Царевич» — на отца-царя, «Попович» — на отца-попа. У Хоттабыча здесь нет имени. По паре «Добрыня Никитич» точно узнаются имя и отчество."]},{"author":"И. Иткин","question":"Как нельзя закончить предложение\n<em>Мышонок испугался и спрятался ...</em>?","choices":["<em>под шкафом</em>","<em>под шкаф</em>","<em>за шкаф</em>","<em>в шкафу</em>","<em>все варианты (А)–(Г) возможны.</em>"],"key":"Д","review":["Куда спрятался мышонок","«Под шкафом» и «в шкафу» отвечают на вопрос «где?». Обе фразы описывают место, где укрылся мышонок.","«Под шкаф» и «за шкаф» отвечают на вопрос «куда?» и указывают направление. Все четыре фразы подходят после «спрятался»."]},{"author":"Л. Фёдорова","question":"Джон захотел открыть русский рыбный ресторан под названием «Ч...деса в реш...те», но засомневался, как правильно написать. Помогите ему правильно вставить буквы:","choices":["<em>у</em>, <em>ы</em>","<em>ю</em>, <em>е</em>","<em>ю</em>, <em>и</em>","<em>у</em>, <em>э</em>","<em>у</em>, <em>е</em>."],"key":"Д","review":["Название рыбного ресторана","В слове «чудеса» действует правило «чу-щу пиши с у». Поэтому в первый пропуск ставь «у».","В «решете» стоит «е»: сравни с «решёткой», где на том же месте под ударением пишется «ё». Название пишется «Чудеса в решете»."]},{"author":"А. Пиперски","question":"В каком падеже формы местоимений <em>он, она, оно, они</em> всегда начинаются с согласного <em>н</em>?","choices":["в родительном","в дательном","в винительном","в творительном","в предложном."],"key":"Д","review":["Начальная буква местоимения","В нескольких падежах возможны формы без «н»: «нет его», «дать ей», «вижу их», «доволен им». Для них же бывают варианты после предлога, например «у него».","У предложного падежа обязательно есть предлог, и после него эти формы начинаются на «н»: «о нём», «о ней», «о них». Подходит предложный падеж."]},{"author":"Н. Валеева","question":"Какой из этих глаголов отвечает на вопрос «Что сделать?»?","choices":["<em>сверкать</em>","<em>скакать</em>","<em>сидеть</em>","<em>слететь</em>","<em>свистеть</em>."],"key":"Г","review":["Вопрос к глаголу","«Сверкать», «скакать», «сидеть» и «свистеть» описывают процессы. К ним подходит вопрос «что делать?».","«Слететь» обозначает завершённое действие: например, «слететь с ветки». Оно отвечает на вопрос «что сделать?»."]},{"author":"А. Бердичевский","question":"Куда дует северо-западный ветер?","choices":["на северо-запад","на юго-восток","порывами то на север, то на запад","порывами то на юг, то на восток","может дуть на северо-запад, а может — на юго-восток."],"key":"Б","review":["Северо-западный ветер","Название ветра говорит, откуда он приходит. Северо-западный ветер приходит с северо-запада.","На карте противоположное направление — юго-восток. Туда будет двигаться воздух."]},{"author":"К. Гилярова","question":"На языке южный киваи, на котором говорит один из народов страны Папуа\n— Новая Гвинея, 2 будет netewa, 4 — netewa netewa, 5 — netewa netewa nao. А как на этом языке будет 3?","choices":["nao","netewa nao","nao netewa","nao nao nao","netewa nao netewa."],"key":"Б","review":["Числа на языке киваи","Слово netewa означает «два». В названии числа четыре оно повторено дважды. Чтобы получить пять, добавили nao, значит, это единица.","Три — это два и ещё один. Запиши сначала «netewa», затем «nao», как в названии пяти единица шла после двоек."]},{"author":"К. Гилярова","question":"Какое из этих сочетаний употребляется реже остальных?","choices":["<em>чёрный день</em>","<em>белая ночь</em>","<em>жёлтый смех</em>","<em>зелёная тоска</em>","<em>розовые очки</em>."],"key":"В","review":["Цвета в выражениях","Вспомни знакомые фразы: отложить на чёрный день, гулять белой ночью, испытывать зелёную тоску, смотреть сквозь розовые очки.","О смехе чаще говорят, что он громкий, весёлый или злой. «Жёлтый смех» не стал таким же привычным выражением, как остальные."]},{"author":"А. Сомин","question":"В фильме «Приключения Буратино» лиса Алиса и кот Базилио поют: «Не прячьте ваши __________ по банкам и углам». Как правильно пишется пропущенное слово?","choices":["<em>денешки</em>","<em>денюшки</em>","<em>денижки</em>","<em>денюжки</em>","<em>денежки</em>."],"key":"Д","review":["Строчка о деньгах","Лиса и кот поют «Не прячьте ваши денежки». В этом ласковом слове для денег вторая гласная пишется так же, как в слове «денежный».","Перед глухим [к] буква «ж» звучит как [ш]. В «денежный» слышно [ж], поэтому пиши «денежки»."]},{"author":"А. Сомин","question":"В «грамматической сказке» А. И. Максакова и Г. А. Тумаковой «Исполнение желаний» волшебник обещает зверям исполнить их желания. При этом он использует некоторое правило, и получается, что лев и тигр могут загадать по одному желанию, заяц — два, а косуля — три. Хитрой лисе захотелось загадать больше желаний. Возможно, вы не читали эту сказку, но всё-таки ответьте: что она для этого сделала?","choices":["сказала волшебнику, что она медведь","спрятала хвост","сказала волшебнику, что она не хищник","сказала волшебнику, что она лисица","покрасила шерсть в серый цвет."],"key":"Г","review":["Как лиса загадала больше","В «лев» и «тигр» по одному слогу, в «за-яц» два, в «ко-су-ля» три. Поэтому число желаний связано со слогами в имени зверя.","У «ли-са» два слога, а у «ли-си-ца» три. Достаточно назвать себя лисицей, чтобы по правилу получить ещё желание."]},{"author":"А. Сомин","question":"Как переводится на русский язык слово, которое по-польски звучит как «сушарка»?","choices":["<em>миксер</em>","<em>пылесос</em>","<em>фен</em>","<em>электробритва</em>","<em>утюг</em>."],"key":"В","review":["Польское название прибора","В слове «сушарка» узнаётся «сушить». Ищи прибор, для которого сушка — главное назначение.","Фен сушит волосы, направляя на них воздух. По-польски фен называют suszarka do włosów, буквально «сушилка для волос»."]},{"author":"Б. Иомдин","question":"Сколько из четырёх названий частей света — <em>север, юг, запад, восток</em> — не имеют и никогда не имели приставки?","choices":["ни одно","одно","два","три","все."],"key":"В","review":["Четыре стороны света","«Запад» связан с тем, как солнце падает за горизонт: в слове была приставка «за-». «Восток» связан с восходом: старинная приставка «вос-» передавала движение вверх.","В названиях «север» и «юг» приставок нет. Из четырёх названий таких два."]},{"author":"А. Иткин","question":"В выражении <em>широкая дорога</em> слово <em>дорога</em> можно заменить словом <em>путь</em>: <em>широкий путь</em>. В четырёх данных ниже выражениях слово <em>дорога</em> тоже можно легко заменить словом <em>путь</em>, а в одном такая замена выглядит необычно. В каком?","choices":["<em>дальняя дорога</em>","<em>долгая дорога</em>","<em>железная дорога</em>","<em>прямая дорога</em>","<em>трудная дорога</em>."],"key":"В","review":["Дорога и путь","Подставь «путь» и поменяй окончания: дальний путь, долгий путь, прямой путь, трудный путь. Эти сочетания сохраняют исходный смысл.","«Железная дорога» — устойчивое название путей и системы для движения поездов. Просто «железный путь» звучит необычно и не передаёт всего значения."]},{"author":"С. Бурлак","question":"В наше время машинам присваивают международные номера. Буквы в них используются такие, которые легко могут прочитать во всех странах Европы. Какого номера точно не может быть?","choices":["О123ТА","Н123ВС","М123БК","Е123ХР","Р123СМ."],"key":"В","review":["Буквы на номерах машин","Ищи буквы, которые одинаково выглядят в кириллице и латинице, например «А», «К», «М» и «О». На номерах могут быть такие общие знаки.","У русской «Б» такого латинского двойника нет. Поэтому варианта «М123БК» быть не может."]},{"author":"Т. Лаврынкина","question":"Какая часть корабля раньше называлась <em>ветрило</em>?","choices":["штурвал","якорь","корма","палуба","парус."],"key":"Д","review":["Старинное название на корабле","В слове «ветрило» слышно «ветер». Найди часть судна, которая использует ветер, чтобы судно двигалось.","Ветер наполняет парус и толкает корабль. Отсюда старинное название паруса «ветрило»."]},{"author":"Е. Добрушина","question":"Гриша пока знает не все правила орфографии и в конце слов всегда ставит мягкий знак после мягких согласных, а после твёрдых — не ставит. Выберите вариант, в котором Гриша все слова напишет правильно.","choices":["<em>морж</em>, <em>дочь</em>, <em>товарищ</em>, <em>чушь</em>","<em>дрожь</em>, <em>мяч</em>, <em>вещь</em>, <em>ландыш</em>","<em>ёж</em>, <em>печь</em>, <em>лещ</em>, <em>шалаш</em>","<em>нож</em>, <em>речь</em>, <em>вещь</em>, <em>грош</em>","<em>дрожь</em>, <em>врач</em>, <em>плющ</em>, <em>сушь</em>."],"key":"Г","review":["Мягкий знак по правилу Гриши","Учитывай звучание: [ж] и [ш] всегда твёрдые, [ч’] и [щ’] всегда мягкие. Гриша допишет «ь» только после «ч» и «щ».","Получится «нож, речь, вещь, грош». В этой строке его способ совпал с нормой, а, например, «дочь» он написал бы верно, но «товарищ» — с лишним «ь»."]},{"author":"Н. Шапиро","question":"В предложении <em>Ма</em><strong><em>кар ни з</em></strong><em>автра, ни послезавтра не приедет</em> спрятано слово <em>карниз</em>. В каком из предложений (А)–(Г) <strong>не</strong> спрятано название осветительного прибора?","choices":["<em>Радовался Полкан, деля бремя славы с Жучкой</em>.","<em>Резкий ветер Моську загнал в подворотню</em>.","<em>Ночью бродить по полю страшно, а утром весело</em>.","<em>Барсик думал, что штор шерстяных не бывает</em>.","Такого предложения нет."],"key":"Б","review":["Скрытые названия светильников","Соедини буквенные кусочки через пробелы: «ПолКАН, ДЕЛЯ БРемя» даёт «канделябр», «по поЛЮ СТРАшно» — «люстра», «шТОР ШЕРстяных» — «торшер».","Эти приборы нашлись в А, В и Г. В предложении о резком ветре и Моське такого названия подряд нет."]},{"author":"Л. Фёдорова","question":"Сколько разных пар по твёрдости — мягкости образуют согласные звуки в скороговорке <em>Сеня вёз сена воз</em>?","choices":["ни одной","одну","две","три","четыре."],"key":"Г","review":["Звуки в скороговорке","Сравни «Сеня» с «сена»: в первом слове [н’], во втором [н]. В «вёз» слышно [в’], в «воз» — [в]. Это уже две пары.","В «Сеня» и «сена» начальное [с’] мягкое, а в конце «вёз» и «воз» оглушается «з» и получается твёрдый [с]. Вместе три разные пары."]},{"author":"К. Гилярова","question":"Белоснежка и Золушка играли в шахматы. Белоснежка выиграла. Вот как рассказали об этом 7 гномов.\nПервый: «Белоснежка выиграла Золушке».\nВторой: «Золушка проиграла Белоснежке».\nТретий: «Белоснежка выиграла Золушку».\nЧетвёртый: «Белоснежка обыграла Золушку».\nПятый: «Белоснежка выиграла у Золушки».\nШестой: «Золушка проиграла у Белоснежки».\nСедьмой: «Белоснежка обыграла у Золушки».\nПеречислите всех гномов, которые точно не сделали ошибки.","choices":["первый и второй","первый, четвёртый и шестой","второй, третий и четвёртый","второй, четвёртый и пятый","пятый, шестой и седьмой."],"key":"Г","review":["Шахматы глазами гномов","К разным глаголам задают разные вопросы: «проиграла кому?», «обыграла кого?», «выиграла у кого?».","По этой схеме правильно сказали второй («проиграла Белоснежке»), четвёртый («обыграла Золушку») и пятый («выиграла у Золушки»)."]},{"author":"И. Рубанов","question":"Сейчас, описывая заготовку леса, говорят, что его <em>рубят</em>. А были времена, когда говорили, что деревья при заготовке","choices":["<em>молотят</em>","<em>бьют</em>","<em>колотят</em>","<em>режут</em>","<em>секут</em>."],"key":"Д","review":["Как раньше заготавливали лес","Дерево для заготовки срубают резким ударом топора. Найди старый глагол, который тоже означает «рубить ударами».","Глагол «сечь» как раз имел такое значение: деревья секут. В слове «лесосека» по-прежнему слышны части «лес» и «сек-»."]},{"author":"Б. Иомдин","question":"Какой из этих шуточных «лозунгов» устроен не так, как другие?","choices":["<em>Норы зверью!</em>","<em>Болота комарью!</em>","<em>Гнёзда совью!</em>","<em>Сыр воронью!</em>","<em>Дорогу дурачью!</em>"],"key":"В","review":["Шуточные лозунги","Поставь слова, которые отвечают на вопрос «кому?», в исходную форму: «зверьё», «комарьё», «вороньё», «дурачьё». Каждое называет целую группу.","В строке «Гнёзда совью!» слово «совью» похоже на форму прилагательного «совий», как в «совью голову». Чтобы назвать получателей гнёзд, в обычной речи говорят «совам»."]},{"author":"Л. Фёдорова","question":"Когда неодобрительно говорят о похожих странностях двух приятелей, вспоминают","choices":["кошку с собакой","яблоню с яблоком","Фому с Ерёмой","Тамару с подружкой","пару сапог."],"key":"Д","review":["Похожие приятели","Ищи устойчивое выражение для двух людей, похожих друг на друга. В нём сравнивают людей с двумя предметами из одной пары.","Поговорка «Два сапога — пара» часто звучит неодобрительно, когда у обоих похожие недостатки. Поэтому вспоминают пару сапог."]},{"author":"И. Рубанов","question":"На вывеске одного петербургского магазина нарисованы три кошачьих фигурки и написана одна буква. Какая это буква?","choices":["<em>Ё</em>","<em>Ж</em>","<em>З</em>","<em>И</em>","<em>Ы</em>."],"key":"Б","review":["Кошки на вывеске","Произнеси количество и название животных вместе: «три кота». Теперь прибавь звук одной буквы из вариантов.","С «ж» выйдет «три-кота-ж», то есть «трикотаж». Это название ткани и изделий, которые мог продавать магазин."]},{"author":"Н. Валеева","question":"Что по смыслу лишнее?","choices":["<em>открыть дверь</em>","<em>открыть заслонку</em>","<em>открыть калитку</em>","<em>открыть квартиру</em>","<em>открыть форточку</em>."],"key":"Г","review":["Что именно открывают?","Дверь, заслонку, калитку и форточку можно отодвинуть или повернуть, чтобы освободить проход или отверстие.","Слова «открыть квартиру» означают открыть дверь или замок квартиры. Здесь названо помещение, а не то, что сдвигают или отпирают."]},{"author":"И. Иткин","question":"O Tite tute Tati, tibi tanta, tyranne, pulisti!\nПеред вами — строка древнеримского поэта Энния (в переводе с латыни она означает: «О не знающий опасностей правитель Тит Татий, как много ты перенёс!»), в которой допущена ошибка. Какое исправление нужно внести, чтобы строка приобрела первоначальный вид?","choices":["заменить tute на tuta","заменить tibi на tebe","заменить tanta на tantum","заменить tyranne на tiranne","заменить pulisti на tulisti."],"key":"Д","review":["Строка на латыни","Посмотри на начала латинских слов: Tite, tute, Tati, tibi, tanta, tyranne. Поэт повторяет «t» почти в каждом слове.","Из вариантов только замена pulisti на tulisti продолжает повтор «t». Так исправляется последнее слово."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
